import 'package:cloud_firestore/cloud_firestore.dart'; import 'package:flutter/material.dart';
class AdminStats extends StatelessWidget{const AdminStats({super.key});Stream<int> count(String x)=>FirebaseFirestore.instance.collection(x).snapshots().map((s)=>s.size);@override Widget build(BuildContext c)=>Wrap(spacing:8,runSpacing:8,children:[_card('Pengguna',count('users'),Icons.people),_card('Produk',count('products'),Icons.inventory),_card('Chat',count('chats'),Icons.chat),_card('Banner',count('banners'),Icons.campaign)]);Widget _card(String label,Stream<int> stream,IconData icon)=>SizedBox(width:160,child:Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon),const SizedBox(height:8),Text(label),StreamBuilder<int>(stream:stream,builder:(c,s)=>Text((s.data??0).toString(),style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold)))]))));}